// src/App.js
import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import Login from './components/Login';
import Signup from './components/Signup';
import RoleSelection from './components/RoleSelection';
import FreelancerForm from './components/FreelancerForm';
import JobSeekerForm from './components/JobSeekerForm';
import ProtectedRoute from './components/ProtectedRoute';

let Dashboard;
try {
  Dashboard = require('./modules/dashboard/Dashboard').default;
} catch {
  Dashboard = () => <div style={{ padding: 24 }}>Dashboard placeholder</div>;
}

export default function App() {
  return (
    <Routes>
      {/* Public */}
      <Route path="/login" element={<Login />} />
      <Route path="/signup" element={<Signup />} />
      <Route path="/role-selection" element={<RoleSelection />} />
      <Route path="/freelancer-form" element={<FreelancerForm />} />
      <Route path="/jobseeker-form" element={<JobSeekerForm />} />

      {/* Protected */}
      <Route
        path="/"
        element={
          <ProtectedRoute>
            <Dashboard />
          </ProtectedRoute>
        }
      />

      <Route path="*" element={<Navigate to="/login" replace />} />
    </Routes>
  );
}
